function ciCommitTree(tree,parents,message){const raw=`tree ${tree}\n${parents.map(parent=>'parent '+parent+'\n').join('')}author Offline ordinary test <offline@example.invalid> 1792231260 +0000\ncommitter Offline ordinary test <offline@example.invalid> 1792231260 +0000\n\n${message}\n`;return localGit(gitFixture().root,['hash-object','-t','commit','-w','--stdin'],raw);}
function ciEnabledChild(parent){const f=gitFixture();checkoutCi(parent);try{const raw=readFileSync(join(f.root,CI_REQUEST)),value=JSON.parse(raw);assert.equal(value.enabled,false);value.enabled=true;value.activation={reviewed_parent_sha:parent,reviewed_parent_tree:localGit(f.root,['rev-parse','HEAD^{tree}']),disabled_request_sha256:sha(raw)};writeFileSync(join(f.root,CI_REQUEST),JSON.stringify(value,null,2)+'\n');localGit(f.root,['add','--',CI_REQUEST]);return ciCommitTree(localGit(f.root,['write-tree']),[parent],'Offline enabled child of '+parent);}finally{localGit(f.root,['reset','--hard','-q','HEAD']);checkoutCi();}}
