test('CI rearm is rejected when any real ancestor previously enabled the same identity',()=>{const local=gitFixture(),rearmParent=ciCommitTree(local.parentTree,[local.head],'Offline disabled after enabled identity'),rearmed=ciEnabledChild(rearmParent);try{const f=ciApiFixture(rearmed);assert.throws(()=>ciActivation(f),/previously enabled|rearm/);}finally{checkoutCi();}});
test('CI ancestry rejects a real side branch that escapes the fixed reviewed base',()=>{const local=gitFixture(),unrelated=ciCommitTree(local.baseTree,[],'Offline unrelated root'),parent=ciCommitTree(local.parentTree,[CI.controller_base.sha,unrelated],'Offline bad preparation merge'),head=ciEnabledChild(parent);try{const f=ciApiFixture(head);assert.throws(()=>ciActivation(f),/escapes reviewed base/);}finally{checkoutCi();}});
test('CI ancestry rejects more than 64 distinct genuine local commits',()=>{const local=gitFixture();let ancestor=CI.controller_base.sha;for(let i=0;i<64;i++)ancestor=ciCommitTree(local.baseTree,[ancestor],'Offline bounded ancestry '+i);const parent=ciCommitTree(local.parentTree,[ancestor],'Offline overbound preparation'),head=ciEnabledChild(parent);try{const f=ciApiFixture(head);assert.throws(()=>ciActivation(f),/exceeds 64 commits/);}finally{checkoutCi();}});
