function ciCliFixture(f,command='ci-admit'){
 const temp=mkdtempSync(join(tmpdir(),'ordinary-ci-cli-')),module=fileURLToPath(new URL('./ordinary-carry-tooling.mjs',import.meta.url));mkdirSync(join(temp,'bin'));
 const mapping={};for(const call of [...f.calls])mapping[JSON.stringify([call.endpoint,call.paginate])]=f.api(call.endpoint,call.paginate);
 writeFileSync(join(temp,'responses.json'),JSON.stringify(mapping));writeFileSync(join(temp,'event.json'),JSON.stringify(f.event));
 const fake=`#!${process.execPath}\nimport fs from 'node:fs';\nconst args=process.argv.slice(2);if(args[0]!=='api'||args[1]!=='--hostname'||args[2]!=='github.com'||args[3]!=='--method'||args[4]!=='GET')throw Error('Offline fixture rejected nonofficial GET');const paginated=args[5]==='--paginate';if(paginated&&args[6]!=='--slurp')throw Error('Missing slurp');const endpoint=args.at(-1);const map=JSON.parse(fs.readFileSync(${JSON.stringify(join(temp,'responses.json'))}));const key=JSON.stringify([endpoint,paginated]);if(!Object.hasOwn(map,key))throw Error('Offline fixture rejected unlisted endpoint '+endpoint);fs.appendFileSync(${JSON.stringify(join(temp,'calls.jsonl'))},JSON.stringify({endpoint,paginated})+'\\n');process.stdout.write(JSON.stringify(map[key]));\n`;
 writeFileSync(join(temp,'bin/gh'),fake,{mode:0o755});
 // Test-only launcher supplies a deterministic clock. Production accepts no
 // such flag, environment override, event replacement, or alternate API.
 writeFileSync(join(temp,'launch.mjs'),`Date.now=()=>${CI_NOW};process.argv=[process.execPath,${JSON.stringify(module)},${JSON.stringify(command)}];await import(${JSON.stringify(new URL('./ordinary-carry-tooling.mjs',import.meta.url).href)});\n`);
 const e=f.execution,env={...process.env,PATH:join(temp,'bin')+':'+process.env.PATH,NODE_OPTIONS:'',NODE_PATH:'',GH_HOST:'untrusted.invalid',GH_TOKEN:'',GITHUB_TOKEN:'',GIT_NO_LAZY_FETCH:'1',GIT_ALLOW_PROTOCOL:'',RUNNER_TEMP:temp,GITHUB_WORKSPACE:f.root,GITHUB_EVENT_PATH:join(temp,'event.json'),GITHUB_OUTPUT:join(temp,'output'),GITHUB_ENV:join(temp,'env'),GITHUB_EVENT_NAME:e.event_name,GITHUB_REPOSITORY:e.repository,GITHUB_REPOSITORY_ID:String(e.repository_id),GITHUB_REF:e.ref,GITHUB_SHA:e.sha,GITHUB_WORKFLOW_REF:e.workflow_ref,GITHUB_WORKFLOW_SHA:e.workflow_sha,GITHUB_RUN_ID:String(e.run_id),GITHUB_RUN_ATTEMPT:String(e.run_attempt)};delete env.ORDINARY_CI_CONTROLLER_ROOT;
 return {temp,module,env,run:()=>spawnSync(process.execPath,[join(temp,'launch.mjs')],{cwd:f.root,env,encoding:'utf8',maxBuffer:3*1024**2,timeout:60000})};
}
