test('CI detached controller preserves full workspace trust without accepting new inputs',async()=>{
 const f=ciApiFixture(),temp=mkdtempSync(join(tmpdir(),'ordinary-ci-worktree-')),cwd=process.cwd(),controller=join(temp,'ordinary-carry-controller');
 try{await ciWithEnv({ORDINARY_CI_CONTROLLER_ROOT:undefined,GITHUB_WORKSPACE:f.root,RUNNER_TEMP:temp,GITHUB_ENV:join(temp,'env'),GITHUB_SHA:f.head,GITHUB_WORKFLOW_SHA:f.head,GITHUB_REF:'refs/heads/main',GITHUB_EVENT_NAME:'workflow_run'},async()=>{
  process.chdir(f.root);assert.deepEqual(prepareOrdinaryCiController(),{prepared:true,head:f.head});assert.match(readFileSync(join(temp,'env'),'utf8'),new RegExp('ORDINARY_CI_CONTROLLER_ROOT='));process.env.ORDINARY_CI_CONTROLLER_ROOT=controller;assert.equal(ordinaryCiControllerRoot(),controller);assert.throws(()=>prepareOrdinaryCiController(),/twice/);
  writeFileSync(join(f.root,'unexpected-controller-input'),'dirty');assert.throws(()=>ordinaryCiControllerRoot(),/untracked/i);rmSync(join(f.root,'unexpected-controller-input'));
  const path=join(f.root,'README.md'),bytes=readFileSync(path);localGit(f.root,['update-index','--assume-unchanged','--','README.md']);try{writeFileSync(path,'dirty hidden workspace');assert.throws(()=>ordinaryCiControllerRoot(),/tracked|bytes|changed/i);}finally{writeFileSync(path,bytes);localGit(f.root,['update-index','--no-assume-unchanged','--','README.md']);}
  writeFileSync(join(controller,'unexpected-clean-root-input'),'dirty');assert.throws(()=>ordinaryCiControllerRoot(),/Untracked/);rmSync(join(controller,'unexpected-clean-root-input'));
  mkdirSync(join(f.root,'release'));writeFileSync(join(f.root,'release/unverified-ui'),'dirty');assert.throws(()=>ordinaryCiControllerRoot(),/selected UI|toplevel|Command failed/);rmSync(join(f.root,'release'),{recursive:true,force:true});
  const alias=join(temp,'linked-controller');symlinkSync(controller,alias);process.env.ORDINARY_CI_CONTROLLER_ROOT=alias;assert.throws(()=>ordinaryCiControllerRoot(),/Unexpected ordinary controller path/);process.env.ORDINARY_CI_CONTROLLER_ROOT=controller;assert.equal(ordinaryCiControllerRoot(),controller);
 });}finally{process.chdir(cwd);if(existsSync(controller))localGit(f.root,['worktree','remove','--force',controller]);rmSync(temp,{recursive:true,force:true});}
});

