function ciExactSource(){const s=CI.source;return {runId:s.run_id,attempt:1,manifestHash:s.manifest_sha256,priceObservationsDigest:s.price_observations_sha256,manifest:{markets:{US:{as_of_date:s.as_of_date}}},artifact:{id:s.artifact_id,size_in_bytes:s.artifact_bytes,digest:'sha256:'+s.artifact_sha256,name:`static-site-data-${s.run_id}-1`,created_at:s.created_at,expired:false,workflow_run:{id:s.run_id,head_sha:s.head_sha,head_branch:'main'}}};}
test('CI selector accepts only the exact original source without manufacturing eligibility',()=>{const source=ciExactSource();assert.equal(assertOrdinaryCiSource(source),source);for(const value of [undefined,null,{},selectionState(CI)])assert.throws(()=>assertOrdinaryCiSource(value),/Newest eligible/);});
for(const [name,mutate]of [['newer artifact',s=>{s.artifact.id++;}],['different run',s=>{s.runId++;}],['rerun',s=>{s.attempt++;}],['wrong artifact run',s=>{s.artifact.workflow_run.id++;}],['wrong source head',s=>{s.artifact.workflow_run.head_sha=g;}],['changed manifest',s=>{s.manifestHash=h;}],['changed observations',s=>{s.priceObservationsDigest=h;}],['changed source date',s=>{s.manifest.markets.US.as_of_date='2026-10-17';}],['source repair',s=>{s.repair={};}],['published receipt',s=>{s.receiptHash=h;}],['published input',s=>{s.publication={};}],['changed size',s=>{s.artifact.size_in_bytes++;}],['changed digest',s=>{s.artifact.digest='sha256:'+h;}],['changed creation',s=>{s.artifact.created_at='2026-10-17T04:00:19Z';}]])test('CI selector rejects '+name+' rather than falling back',()=>{const source=ciExactSource();mutate(source);assert.throws(()=>assertOrdinaryCiSource(source),/Newest eligible/);});
test('CI normal newest eligible export wins selection and a source race aborts without pinned fallback',()=>{
 const date='2026-10-17',id=CI.source.run_id+1,created='2026-10-17T05:00:00Z',manifest=d=>({as_of_date:d,default_market:'US',supported_markets:['US'],markets:{US:{as_of_date:d,freshness:{scan_as_of_date:d,scan_published_at:d+'T01:00:00Z',prices_generated_at:d+'T02:00:00Z',breadth_latest_date:d,groups_latest_date:d}}}}),raw=JSON.stringify(manifest(date));
 const artifact={id:CI.source.artifact_id+1,name:`static-site-data-${id}-1`,expired:false,created_at:created,workflow_run:{id,head_sha:CI.source.head_sha,head_branch:'main'},size_in_bytes:100,digest:'sha256:'+h},companion={...clone(artifact),id:artifact.id+1,name:`static-site-data-manifest-${id}-1`},older=ciExactSource().artifact;
 const run={id,run_attempt:1,head_sha:CI.source.head_sha,head_branch:'main',path:'.github/workflows/static-site.yml',event:'schedule',status:'completed',conclusion:'success',repository:CI_REPOSITORY,head_repository:CI_REPOSITORY};
 const job={id:9999,name:'combine-and-build',run_attempt:1,conclusion:'success',started_at:'2026-10-17T04:59:00Z',completed_at:'2026-10-17T05:01:00Z',steps:[{name:'Build static frontend',conclusion:'success'}]};
 const calls=[],api=endpoint=>{calls.push(endpoint);if(endpoint===`${CI_PREFIX}/actions/runs/${id}/attempts/1`)return clone(run);if(endpoint===`${CI_PREFIX}/actions/runs/${id}/attempts/1/jobs?per_page=100`)return[{jobs:[clone(job)]}];assert.fail('Selector unexpectedly fell back to pinned source');};
 const chosen=chooseExport({manifest:manifest('2026-10-16'),knownPriceDates:{}},[{artifacts:[older,artifact,companion]}],CI_REPOSITORY.full_name,api,item=>{assert.equal(item.id,companion.id);return {run_id:id,run_attempt:1,source_sha:run.head_sha,artifact_name:artifact.name,manifest_json:raw,manifest_sha256:sha(raw),price_observations:{},price_observations_sha256:sha('{}')};});
 assert.equal(chosen.artifact.id,artifact.id);assert.throws(()=>assertOrdinaryCiSource(chosen),/Newest eligible/);assert(calls.every(e=>e.includes('/'+id+'/')));
});
